from pathlib import Path
import hashlib,json,re,shutil
lab=Path('F:/Projects/tyrax2-lab-20261001')
src=lab/'arena-check-night/game'
dst=lab/'light-split/game'
assert not (dst/"bin/vehicle-playground.elf").exists()
shutil.copytree(src,dst,dirs_exist_ok=True,ignore=shutil.ignore_patterns('obj','*.log','*.elf','*.elf.sym','*.p2s','ps2link.run'))
header=r'''#pragma once
#include <cstdio>
#include "debug/frame_profile.hpp"
namespace lightSplit {
inline unsigned phase=0;
inline unsigned long long ticks[5]={};
inline unsigned calls[5]={};
inline unsigned poolRebuild=0, beamRebuild=0;
struct Scope {
  unsigned index, begin;
  explicit Scope(unsigned i):index(i),begin(Tyra::FrameProfile::ticks()) {}
  ~Scope(){ ticks[index]+=unsigned(Tyra::FrameProfile::ticks()-begin); ++calls[index]; }
};
template<class F> inline void render(unsigned i,F f){ Scope s(i); f(); }
inline void report(unsigned frame){
  static unsigned previous=0;
  if(!frame || frame%50 || frame==previous) return;
  const unsigned n=frame-previous; previous=frame;
  printf("LOG: LIGHTSPLIT phase=%u f=%u n=%u pool=%.4f render=%.4f recv=%.4f beam=%.4f render=%.4f poolcalls=%u beamcalls=%u rebuild=%u/%u\n",
    phase,frame,n,float(ticks[0])/294912/n,float(ticks[1])/294912/n,
    float(ticks[2])/294912/n,float(ticks[3])/294912/n,float(ticks[4])/294912/n,
    calls[1],calls[4],poolRebuild,beamRebuild);
  for(unsigned i=0;i<5;++i){ticks[i]=0;calls[i]=0;}
  poolRebuild=beamRebuild=0;
}
}
'''
(dst/'inc/light_split.hpp').write_bytes(header.encode())
def edit(rel,old,new):
 p=dst/rel; s=p.read_text(encoding='utf-8'); assert s.count(old)==1,(rel,old,s.count(old)); p.write_bytes(s.replace(old,new).encode())
for rel in ['src/terrain_game.cpp','src/gen/game_lighting.gen.cpp']:
 p=dst/rel; p.write_bytes(('#include "light_split.hpp"\n'+p.read_text(encoding='utf-8')).encode())
edit('src/terrain_game.cpp','void TerrainGame::loop() {',r'''void TerrainGame::loop() {
  lightSplit::report(ftrig::frame);
  static bool announced=false,done=false;
  if(!announced){printf("LOG: LIGHTSPLITPHASE phase=0 first=%lu\n",(unsigned long)ftrig::frame);fflush(stdout);announced=true;}
  const unsigned desired=ftrig::frame/2200;
  if(desired<=4 && desired!=lightSplit::phase){
    engine->renderer.core.synchronizeFrame();lightSplit::phase=desired;
    printf("LOG: LIGHTSPLITPHASE phase=%u first=%lu\n",desired,(unsigned long)ftrig::frame);fflush(stdout);
    loadScene(currentScene);
  }
  if(desired>4 && !done){printf("LOG: LIGHTSPLITPHASE done first=%lu\n",(unsigned long)ftrig::frame);fflush(stdout);done=true;}
''')
rel='src/gen/game_lighting.gen.cpp'
edit(rel,'void TerrainGame::updateAndRenderLightPools() {','''void TerrainGame::updateAndRenderLightPools() {
  if(lightSplit::phase==1 || lightSplit::phase==3) return;
  lightSplit::Scope timing(0);''')
edit(rel,'const Vec4* viewAt, int portal) {','''const Vec4* viewAt, int portal) {
  if(lightSplit::phase==2 || lightSplit::phase==3) return;
  lightSplit::Scope timing(3);''')
edit(rel,'  if (pb.key != pb.lastKey) {','  if (pb.key != pb.lastKey) {\n    ++lightSplit::poolRebuild;')
edit(rel,'      if (cw) bb.coronaBag->bboxVersion = ++g_bboxStamp;','      if (cw) { ++lightSplit::beamRebuild; bb.coronaBag->bboxVersion = ++g_bboxStamp; }')
edit(rel,'      if (nw) bb.coneBag->bboxVersion = ++g_bboxStamp;','      if (nw) { ++lightSplit::beamRebuild; bb.coneBag->bboxVersion = ++g_bboxStamp; }')
p=dst/rel;s=p.read_text(encoding='utf-8')
# Include the pool-batch helper in submission time, plus every render call
# within the pool and beam functions. Keep unrelated shadow passes untouched.
for start,end,bucket in [('void TerrainGame::poolBatchFlush()', '// Blob shadows: per-scene setup.',1),('void TerrainGame::updateAndRenderLightBeams(', '// Runtime texts:',4)]:
 a=s.index(start);b=s.index(end,a);part=s[a:b]
 part,n=re.subn(r'(stapip\.core\.render\([^;]+\);)',lambda m:'lightSplit::render('+str(bucket)+',[&] { '+m[1]+' });',part)
 assert n==(9 if bucket==1 else 4),(bucket,n)
 s=s[:a]+part+s[b:]
# Receiver collection is shared with shadow passes; count only collection
# while the pool pass is active, using a separate scope flag.
# For this fixture the selected garage pools use these three explicit calls.
a=s.index('void TerrainGame::updateAndRenderLightPools()');b=s.index('// Blob shadows: per-scene setup.',a)
part=s[a:b]
part,n=re.subn(r'((?:projCollectReceivers|projCollectBoxes)\([^;]+\);)',lambda m:'{ lightSplit::Scope receiverTiming(2); '+m[1]+' }',part)
assert n==3,n
s=s[:a]+part+s[b:];p.write_bytes(s.encode())
files=[dst/'inc/light_split.hpp',dst/'src/terrain_game.cpp',p]
meta={'phases':['full night before','no scene pools','no scene beams/coronas','no scene pools or beams','full night restored'], 'frames_per_phase':2200,'warm_work_start_offset':1100,'work_sample_count':512,'engine':str(lab/'arena-check-night/tyra'),'source_game':str(src),'artifacts':{str(p.relative_to(dst)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files},'profile_note':'Scratch per-pass COP0 duration includes EE work and submission waits; render subtime is included in total, not additive. Does not measure GS raster utilization.'}
(lab/'light-split/fixture.json').write_bytes((json.dumps(meta,indent=2)+'\n').encode())
print(meta['phases'])
